// content/async.md #1
func contentCode8(contentCodeParent *core.Frame, contentCodeOut io.Writer) {
	b := contentCodeParent
	_ = b
	{
		text := core.NewText(b)
		text.Updater(func() {
			text.SetText(time.Now().Format("15:04:05"))
		})
		go func() {
			for range time.Tick(time.Second) {
				if !text.IsVisible() {
					continue
				}
				text.AsyncLock()
				text.UpdateRender()
				text.AsyncUnlock()
			}
		}()

	}
}

