// content/tic-tac-toe-tutorial.md #2
func contentCode301(contentCodeParent *core.Frame, contentCodeOut io.Writer) {
	b := contentCodeParent
	_ = b
	{
		current := "X"
		squares := [9]string{}
		grid := core.NewFrame(b)
		grid.Styler(func(s *styles.Style) {
			s.Display = styles.Grid
			s.Columns = 3
		})
		for i := range 9 {
			bt := core.NewButton(grid).SetType(core.ButtonAction)
			bt.Styler(func(s *styles.Style) {
				s.Border.Width.Set(units.Dp(1))
				s.Border.Radius.Zero()
				s.Min.Set(units.Em(2))
			})
			bt.OnClick(func(e events.Event) {
				// don't set squares that already have a value
				if squares[i] != "" {
					return
				}
				squares[i] = current
				if current == "X" {
					current = "O"
				} else {
					current = "X"
				}
				bt.Update()
			})
			bt.Updater(func() {
				bt.SetText(squares[i])
			})
		}
		core.NewButton(b).SetText("Reset").OnClick(func(e events.Event) {
			squares = [9]string{}
			current = "X"
			grid.Update()
		})

	}
}

// content/tic-tac-toe-tutorial.md #3
func contentCode302(contentCodeParent *core.Frame, contentCodeOut io.Writer) {
	b := contentCodeParent
	_ = b
	{
		current := "X"
		squares := [9]string{}
		status := core.NewText(b)
		status.Updater(func() {
			sets := [][3]int{ // possible sets of three that result in a win
				{0, 1, 2}, {3, 4, 5}, {6, 7, 8}, {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, {0, 4, 8}, {2, 4, 6},
			}
			// check if someone has won
			for _, set := range sets {
				if squares[set[0]] != "" && squares[set[0]] == squares[set[1]] && squares[set[0]] == squares[set[2]] {
					status.SetText(squares[set[0]] + " wins!")
					current = ""
					return
				}
			}
			status.SetText("Next player: " + current)
		})
		grid := core.NewFrame(b)
		grid.Styler(func(s *styles.Style) {
			s.Display = styles.Grid
			s.Columns = 3
		})
		for i := range 9 {
			bt := core.NewButton(grid).SetType(core.ButtonAction)
			bt.Styler(func(s *styles.Style) {
				s.Border.Width.Set(units.Dp(1))
				s.Border.Radius.Zero()
				s.Min.Set(units.Em(2))
			})
			bt.OnClick(func(e events.Event) {
				// don't set squares if they already have a value or the game is over
				if squares[i] != "" || current == "" {
					return
				}
				squares[i] = current
				if current == "X" {
					current = "O"
				} else {
					current = "X"
				}
				bt.Update()
				status.Update()
			})
			bt.Updater(func() {
				bt.SetText(squares[i])
			})
		}
		core.NewButton(b).SetText("Reset").OnClick(func(e events.Event) {
			squares = [9]string{}
			current = "X"
			grid.Update()
			status.Update()
		})

	}
}

